// <auto-generated />
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import type { UseQueryOptions, UseMutationOptions } from '@tanstack/react-query';
import { useApiService } from './useApiService';
import { ApiError } from '../errors/ApiError';
import type { Pet, Pets } from '../models';

const petsKeys = {
  all: ['pets'] as const,
  list: (query?: { limit?: number }) => [...petsKeys.all, 'list', query] as const,
  showPetById: (petId: string) => [...petsKeys.all, 'showPetById', petId] as const,
};

export { petsKeys };

export function useListPets(query?: { limit?: number }, options?: Omit<UseQueryOptions<Pets, ApiError>, 'queryKey' | 'queryFn'>) {
  const api = useApiService();
  return useQuery({
    queryKey: petsKeys.list(query),
    queryFn: async () => {
      const result = await api.pets.listPets(query);
      if (result.status === 'ok') {
        return result.data;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    ...options,
  });
}

export function useCreatePets(options?: Omit<UseMutationOptions<void, ApiError, void>, 'mutationFn'>) {
  const api = useApiService();
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async () => {
      const result = await api.pets.createPets();
      if (result.status === 'created') {
        return;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    ...options,
    onSuccess: (data, variables, context) => {
      queryClient.invalidateQueries({ queryKey: petsKeys.all });
      options?.onSuccess?.(data, variables, context);
    },
  });
}

export function useShowPetById(petId: string, options?: Omit<UseQueryOptions<Pet, ApiError>, 'queryKey' | 'queryFn'>) {
  const api = useApiService();
  return useQuery({
    queryKey: petsKeys.showPetById(petId),
    queryFn: async () => {
      const result = await api.pets.showPetById(petId);
      if (result.status === 'ok') {
        return result.data;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    enabled: !!petId,
    ...options,
  });
}